mapper.select:
SELECT  FROM s_content_report

    status = #{status}
    AND reporter_user_id = #{userId}

ORDER BY created_at DESC, id DESC LIMIT 200

SELECT 
FROM s_content_appeal a JOIN s_content_moderation_log l ON l.id = a.moderation_log_id

    a.status = #{status}
    AND a.appellant_user_id = #{userId}

ORDER BY a.created_at DESC, a.id DESC LIMIT 200

SELECT id, content_type AS targetType, content_id AS targetId, revision_id AS revisionId,
       action, reason, created_at AS createdAt
FROM s_content_moderation_log WHERE id = #{logId}
